  function fromStruct(st, carried) { return { t: st.t.map((t) => ({ n: t.n, f: t.f.map((f) => [f[0], f[1] ? 1 : 0, f[2] ? 1 : 0]), u: 0, carried: !!carried, given: false })), x: (st.x || []).slice(), s: Object.assign({}, st.s || {}) }; }
  function freshWs(q) { if (q.start) return fromStruct(q.start, true); if (q.names) return { t: q.names.map((n) => ({ n, f: [], u: 0, carried: false, given: true })), x: [], s: {} }; return { t: [], x: [], s: {} }; }
